#include <bits/stdc++.h>
using namespace std;

bool dfs(int u, int n, int k, const string &s, vector<bool> &used) {
    if (u < 0 || u >= n || used[u] || s[u] == '#') return false;
    if (s[u] == 'T') return true;
    used[u] = true;
    return dfs(u - k, n, k, s, used) || dfs(u + k, n, k, s, used);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    string s;
    cin >> s;

    vector<bool> used(n, false);
    int start = s.find('G');

    bool res = dfs(start, n, k, s, used);
    cout << (res ? "YES" : "NO") << '\n';

    return 0;
}

